const fingerprintPayload = $('Fetch Scout Fingerprints').first()?.json ?? {};
const fingerprints = Array.isArray(fingerprintPayload.fingerprints) ? fingerprintPayload.fingerprints : [];
const knownKeys = new Set();
for (const fingerprint of fingerprints) {
  if (fingerprint.title_hash) knownKeys.add(String(fingerprint.title_hash));
  if (fingerprint.url) knownKeys.add(String(fingerprint.url));
}

const fetchFailures = [];
const ideas = [];
const normalizeTitle = (title) => title.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 160);

for (const item of $input.all()) {
  const payload = item.json ?? {};
  const requestError = payload.error || payload.errorMessage || payload.message || null;
  if (requestError) {
    fetchFailures.push(String(requestError));
    continue;
  }

  const posts = Array.isArray(payload?.data?.children) ? payload.data.children : [];
  for (const post of posts) {
    const data = post?.data ?? {};
    const ups = Number(data.ups || 0);
    const title = String(data.title || '').trim();
    const url = 'https://www.reddit.com' + String(data.permalink || '');
    const titleHash = normalizeTitle(title);
    if (!title || ups <= 10) continue;
    if (knownKeys.has(titleHash) || knownKeys.has(url)) continue;
    knownKeys.add(titleHash);
    knownKeys.add(url);

    ideas.push({
      source: 'reddit',
      title,
      description: String(data.selftext || '').substring(0, 1000),
      url,
      confidence_score: Math.min(1, ups / 100),
    });
  }
}

return [{
  json: {
    ideas,
    ideaCount: ideas.length,
    fetchFailures,
    fetchedAt: new Date().toISOString(),
  },
}];

