const strategyId = $input.first().json.body?.strategy_id;
if (!strategyId || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(strategyId)) {
  throw new Error('Invalid strategy_id: must be a valid UUID');
}
return [{ json: { strategy_id: strategyId } }];

// Poll backtest until complete — uses n8n this.helpers.httpRequest (Code nodes don't have global fetch)
const backtestId = $input.first().json.backtestId;
const maxAttempts = 20; // 20 x 15s = 5 min
const interval = 15000;

for (let i = 0; i < maxAttempts; i++) {
  const data = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://tf-relay-production.up.railway.app/api/backtests/${backtestId}`,
    json: true,
  });

  if (data.status === 'completed') {
    return [{ json: data }];
  }
  if (data.status === 'failed') {
    throw new Error(`Backtest failed: ${data.error || 'unknown'}`);
  }

  await new Promise(resolve => setTimeout(resolve, interval));
}

throw new Error('Backtest timed out after 5 minutes');

