const response = $input.first().json;
const rulesets = response.rulesets || response.data || response;
const firmSet = new Set();

if (Array.isArray(rulesets)) {
  for (const r of rulesets) {
    const firm = r.firm || r.firmName || r.name;
    if (firm) firmSet.add(firm);
  }
} else if (typeof rulesets === 'object') {
  for (const key of Object.keys(rulesets)) {
    firmSet.add(key);
  }
}

const firms = Array.from(firmSet);
return firms.map(firm => ({ json: { firm } }));

const item = $input.first().json;
const firm = item.firm || item.name || 'Unknown';
const status = item.status || item.verificationStatus || 'unknown';
const ageHours = item.ageHours || item.age_hours || 0;
const drift = item.drift_detected || item.driftDetected || false;

let health = 'healthy';
if (drift) health = 'unhealthy';
else if (status !== 'verified' && status !== 'active') health = 'unhealthy';
else if (ageHours > 168) health = 'unhealthy';
else if (ageHours > 72) health = 'degraded';

return [{
  json: {
    firm,
    status,
    age_hours: Math.round(ageHours * 10) / 10,
    drift,
    health
  }
}];

const items = $input.all();
const firms = items.map(item => item.json);

let healthy = 0;
let unhealthy = 0;
let degraded = 0;

for (const f of firms) {
  if (f.health === 'healthy') healthy++;
  else if (f.health === 'unhealthy') unhealthy++;
  else if (f.health === 'degraded') degraded++;
}

const now = new Date();
const reportDate = now.toISOString().split('T')[0];

return [{
  json: {
    report_date: reportDate,
    firms,
    summary: {
      healthy,
      unhealthy,
      degraded,
      total: firms.length
    },
    generated_at: now.toISOString()
  }
}];

